/**
 * Renders a registry as the generated files of RFC 0002 §7.7: `schema.d.ts` (interfaces only, relations by model
 * name, methods typed from the module sources) plus the typed re-exports next to it.
 */
import { createHash } from 'node:crypto';
import { dirname, relative } from 'node:path';
import type { Field, ModuleBase, RegisteredModel, Registry } from '@shutro/core';
import { CORE_PACKAGE } from '../packages.js';

/** A module and the file it is exported from. */
export interface ModuleSource {
  readonly module: ModuleBase;
  readonly file: string;
  readonly exportName: string;
}

const HEADER = '// GENERATED by `shutro generate`. Do not edit.';

/** Short, stable hash of everything the view depends on (RFC 0002 §7.7 "definitions hash"). */
export function definitionsHash(registry: Registry): string {
  const names = [...registry.models.keys()].sort();
  const definitions = {
    modules: registry.modules.map((m) => [m.name, m.version]),
    models: names.map((name) => registry.describe(name)),
  };
  return createHash('sha256').update(JSON.stringify(definitions)).digest('hex').slice(0, 16);
}

/** `sale.order.line` → `SaleOrderLine`. */
export function interfaceName(model: string): string {
  return model
    .split(/[._]/)
    .map((s) => s.charAt(0).toUpperCase() + s.slice(1))
    .join('');
}

function quote(value: string): string {
  return `'${value.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
}

function union(values: readonly string[]): string {
  return values.length === 0 ? 'never' : values.map(quote).join(' | ');
}

/**
 * The option literal that reproduces the field's phantom flags through `FlagsOf`. Properties are `readonly`, as
 * the builders' `const` type parameters infer them: TypeScript's identity relation tells the two apart, and the
 * generated field must be identical to the declared one.
 */
function flagOptions(field: Field): string {
  const parts: string[] = [];
  if (field.required) parts.push('required: true');
  if (field.readonly) parts.push('readonly: true');
  if (field.default !== undefined) parts.push('default: true');
  if (field.computed) {
    parts.push(`compute: ${typeof field.compute === 'string' ? quote(field.compute) : 'true'}`);
    if (field.store) parts.push('store: true');
  }
  if (field.inverse !== undefined) parts.push('inverse: true');
  if (field.translate) parts.push('translate: true');
  if (field.sequence !== undefined) parts.push('sequence: true');
  return parts.length === 0 ? '' : `{ ${parts.map((p) => `readonly ${p}`).join('; ')} }`;
}

function generic(name: string, ...args: readonly string[]): string {
  const given = args.filter((a) => a !== '');
  return given.length === 0 ? `F.${name}` : `F.${name}<${given.join(', ')}>`;
}

function selectionValues(field: Field): string {
  const selection = (field as { selection?: unknown }).selection;
  if (!Array.isArray(selection)) return 'string';
  return union((selection as readonly (readonly [string, string])[]).map(([value]) => value));
}

/** The `F.*` type of one field. */
export function fieldType(model: string, key: string, field: Field): string {
  const o = flagOptions(field);
  const target = (field as { target?: string }).target ?? '';
  switch (field.kind) {
    case 'bigint':
      return key === 'id' ? generic('Id', quote(model)) : generic('Bigint', o);
    case 'char':
      return generic('Char', o);
    case 'text':
      return generic('Text', o);
    case 'html':
      return generic('Html', o);
    case 'boolean':
      return generic('Bool', o);
    case 'integer':
      return generic('Integer', o);
    case 'float':
      return generic('Float', o);
    case 'decimal':
      return generic('Decimal', o);
    case 'monetary':
      return generic(
        'Monetary',
        quote((field as unknown as { currencyField: string }).currencyField),
        o,
      );
    case 'quantity':
      return generic('Quantity', quote((field as unknown as { uomField: string }).uomField), o);
    case 'selection':
      return generic('Selection', selectionValues(field), o);
    case 'state':
      return generic('State', selectionValues(field), o);
    case 'json':
      return generic('Json', o === '' ? '' : 'unknown', o);
    case 'binary':
      return generic('Binary', o);
    case 'date':
      return generic('DateOnly', o);
    case 'datetime':
      return generic('Datetime', o);
    case 'many2one':
      return generic('Many2one', quote(target), o);
    case 'one2many':
      return generic('One2many', quote(target), o);
    case 'many2many':
      return generic('Many2many', quote(target), o);
    default:
      throw new Error(`Unknown field kind ${JSON.stringify(field.kind)} on ${model}.${key}.`);
  }
}

/** Import specifier of `file` from a file in `fromDir`, in ESM spelling (`../module.js`). */
export function importSpecifier(fromDir: string, file: string): string {
  const spec = relative(fromDir, file).replace(/\\/g, '/').replace(/\.ts$/, '.js');
  return spec.startsWith('.') ? spec : `./${spec}`;
}

function methodsType(
  registered: RegisteredModel,
  sources: ReadonlyMap<string, ModuleSource>,
  outDir: string,
): string {
  const contributors = [registered.module, ...registered.extensions];
  const parts = contributors.map((name) => {
    const source = sources.get(name);
    if (source === undefined) throw new Error(`No source for module '${name}'.`);
    const spec = importSpecifier(outDir, source.file);
    return `F.Methods<typeof import(${quote(spec)}).${source.exportName}, ${quote(registered.model.name)}>`;
  });
  return parts.join(' & ');
}

/** Renders `schema.d.ts` for a registry (a module view or the application view). */
export function renderSchema(
  registry: Registry,
  sources: ReadonlyMap<string, ModuleSource>,
  outDir: string,
  title: string,
): string {
  const names = [...registry.models.keys()].sort();
  const lines: string[] = [
    `${HEADER} definitions-hash: ${definitionsHash(registry)}`,
    `// ${title}`,
    `import type { F } from '${CORE_PACKAGE}';`,
    '',
    '/** Model name → model type (RFC 0002 §7.7). */',
    'export interface SchemaView {',
    ...names.map((name) => `  readonly ${quote(name)}: ${interfaceName(name)};`),
    '}',
  ];
  for (const name of names) {
    const registered = registry.get(name);
    const { model } = registered;
    const origin =
      registered.extensions.length === 0
        ? `owner: ${registered.module}`
        : `owner: ${registered.module}; extended by: ${registered.extensions.join(', ')}`;
    lines.push('', `/** \`${name}\` (${origin}). */`, `export interface ${interfaceName(name)} {`);
    lines.push(`  readonly name: ${quote(name)};`, '  readonly fields: {');
    for (const [key, field] of Object.entries(model.fields)) {
      const from = registered.fieldOrigins[key];
      const comment = from === undefined || from === registered.module ? '' : ` // ${from}`;
      lines.push(`    readonly ${key}: ${fieldType(name, key, field)};${comment}`);
    }
    lines.push('  };', `  readonly methods: ${methodsType(registered, sources, outDir)};`, '}');
  }
  return `${lines.join('\n')}\n`;
}

const ALIASES = [
  `import type { DefaultLoaded, Env as CoreEnv, RecordSet as CoreRecordSet, Shutro as CoreShutro } from '${CORE_PACKAGE}';`,
  "import type { SchemaView } from './schema.js';",
  '',
  'export type { SchemaView };',
  '/** Every model visible in this view. */',
  'export type ModelName = keyof SchemaView & string;',
  '/** `Env` typed to this view. */',
  'export type Env = CoreEnv<SchemaView>;',
  '/** `Shutro` typed to this view. */',
  'export type Shutro = CoreShutro<SchemaView>;',
  '/** A recordset of `M`, with the default loaded shape unless `L` is given. */',
  'export type Records<M extends ModelName, L = DefaultLoaded<SchemaView, M>> = CoreRecordSet<SchemaView, M, L>;',
];

/** Renders `bindings.ts` for a module: the definition API plus aliases typed to its view. */
export function renderBindings(registry: Registry, module: string): string {
  return `${[
    `${HEADER} definitions-hash: ${definitionsHash(registry)}`,
    `// Bindings of module \`${module}\`: import the definition API from here to get types scoped to what it can see.`,
    `export { defineModel, defineModule, extendModel, f, replace } from '${CORE_PACKAGE}';`,
    ...ALIASES,
  ].join('\n')}\n`;
}

/** Renders the application's `index.ts`: `createShutro` typed to the full view. */
export function renderAppIndex(registry: Registry): string {
  return `${[
    `${HEADER} definitions-hash: ${definitionsHash(registry)}`,
    '// Application view: every installed module. Build the registry from the same modules and pass it here.',
    `import { createShutro as coreCreateShutro, type Registry, type ShutroOptions } from '${CORE_PACKAGE}';`,
    ...ALIASES,
    '',
    '/** `createShutro` whose environments are typed to the application view. */',
    "export function createShutro(options: Omit<ShutroOptions<SchemaView>, 'registry'> & { readonly registry: Registry }): Shutro {",
    '  return coreCreateShutro<SchemaView>(options as ShutroOptions<SchemaView>);',
    '}',
  ].join('\n')}\n`;
}

/** Directory of the generated files of a module file. */
export function outDirOf(file: string): string {
  return `${dirname(file)}/.shutro`;
}
